    tags_json: "{\"subcategory\":\"fill_in_trial_balance\",\"pattern\":\"fill_in_trial_balance\",\"examSection\":3,\"keywords\":[\"仮払金\",\"仮受金\",\"精算\",\"振替処理\"]}",
